/**
 * Real ONNX bundles generated by `ml/modelops_ml/fixtures.py` (tests/fixtures/bundles), plus
 * helpers to derive deliberately broken variants from them for negative tests.
 */
import { randomBytes } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const DIR = join(process.cwd(), '..', '..', 'tests', 'fixtures', 'bundles');

export type BundleKind = 'sklearn' | 'pytorch';

export interface Bundle {
  framework: 'SKLEARN_ONNX' | 'PYTORCH_ONNX';
  sha256: string;
  bytes: number;
  model: Buffer;
  signature: Buffer;
  golden: Buffer;
}

interface Manifest {
  framework: Bundle['framework'];
  sha256: string;
  bytes: number;
}

export function loadBundle(kind: BundleKind): Bundle {
  const manifest = JSON.parse(readFileSync(join(DIR, 'manifest.json'), 'utf8')) as Record<
    BundleKind,
    Manifest
  >;
  const m = manifest[kind];
  return {
    framework: m.framework,
    sha256: m.sha256,
    bytes: m.bytes,
    model: readFileSync(join(DIR, kind, 'model.onnx')),
    signature: readFileSync(join(DIR, kind, 'signature.json')),
    golden: readFileSync(join(DIR, kind, 'golden_examples.json')),
  };
}

/** The same golden examples with a unique byte layout (different sha256, same meaning). */
export function uniqueGolden(golden: Buffer): Buffer {
  // 128 random bits written as JSON whitespace (space = 0, tab = 1): collisions are negligible.
  const pad = [...randomBytes(16)]
    .flatMap((byte) => byte.toString(2).padStart(8, '0').split(''))
    .map((bit) => (bit === '1' ? '\t' : ' '))
    .join('');
  return Buffer.concat([golden, Buffer.from(`${pad}\n`)]);
}

/**
 * The same ONNX model with a unique SHA-256: appends a `doc_string` field (ModelProto field 6,
 * length-delimited). Protobuf keeps the last value of a repeated singular field, and neither ONNX
 * nor ONNX Runtime use doc_string, so the model behaves identically. Lets a test tamper with
 * "its own" content-addressed blob without touching blobs other tests (or runs) share.
 */
export function uniqueModel(model: Buffer): Buffer {
  const doc = Buffer.from(`test-${randomBytes(12).toString('hex')}`, 'utf8'); // < 128 bytes
  return Buffer.concat([model, Buffer.from([0x32, doc.length]), doc]);
}

/** Golden examples whose expected labels are all flipped: the model can no longer reproduce them. */
export function flippedGolden(golden: Buffer): Buffer {
  const g = JSON.parse(golden.toString('utf8')) as { outputs: { label: number[] } };
  g.outputs.label = g.outputs.label.map((l) => 1 - l);
  return Buffer.from(JSON.stringify(g));
}

/** A well-formed signature whose input name does not exist in the graph. */
export function renamedInputSignature(signature: Buffer): Buffer {
  const s = JSON.parse(signature.toString('utf8')) as { inputs: { name: string }[] };
  const first = s.inputs[0];
  if (first) first.name = 'not_the_graph_input';
  return Buffer.from(JSON.stringify(s));
}

/** A Python pickle (protocol 4) that would run `os.system` when unpickled. Never loaded. */
export const PICKLE_PAYLOAD = Buffer.concat([
  Buffer.from([0x80, 0x04, 0x95]),
  Buffer.from("cos\nsystem\n(S'touch /tmp/pwned'\ntR.", 'latin1'),
]);
